    img: "",
    tags: ["ringworm", "dermatophytosis", "Trichophyton verrucosum", "Microsporum canis", "keratinase", "Adamson fringe", "kerion", "favus", "scutula", "KOH mount", "Wood lamp", "PAS", "GMS", "ectothrix", "zoonosis"]
